create table public.teams(id uuid primary key default gen_random_uuid(),name text not null,site_name text not null,owner_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(site_name,name));
create table public.team_memberships(team_id uuid not null references public.teams(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'PENDING' check(status in ('PENDING','APPROVED')),is_leader boolean not null default false,created_at timestamptz not null default now(),primary key(team_id,user_id));
alter table public.teams enable row level security;alter table public.team_memberships enable row level security;
create policy "teams authenticated read" on public.teams for select to authenticated using(true);
create policy "members team member manager read" on public.team_memberships for select to authenticated using((select private.is_manager()) or user_id=(select auth.uid()) or exists(select 1 from public.team_memberships m where m.team_id=team_id and m.user_id=(select auth.uid()) and m.status='APPROVED'));
create or replace function public.create_team(p_name text,p_site_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid();v_id uuid;begin if v_user is null then raise exception 'Authentication required';end if;insert into public.teams(name,site_name,owner_id) values(p_name,p_site_name,v_user) returning id into v_id;insert into public.team_memberships(team_id,user_id,status,is_leader) values(v_id,v_user,'APPROVED',true);return v_id;end;$$;
create or replace function public.join_team(p_team_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Authentication required';end if;insert into public.team_memberships(team_id,user_id) values(p_team_id,auth.uid()) on conflict(team_id,user_id) do nothing;end;$$;
create or replace function public.review_team_member(p_team_id uuid,p_user_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$ begin if not (select private.is_manager()) and not exists(select 1 from public.team_memberships where team_id=p_team_id and user_id=auth.uid() and is_leader and status='APPROVED') then raise exception 'Team leader required';end if;if p_approve then update public.team_memberships set status='APPROVED' where team_id=p_team_id and user_id=p_user_id;else delete from public.team_memberships where team_id=p_team_id and user_id=p_user_id and not is_leader;end if;end;$$;
revoke all on function public.create_team(text,text),public.join_team(uuid),public.review_team_member(uuid,uuid,boolean) from public,anon;grant execute on function public.create_team(text,text),public.join_team(uuid),public.review_team_member(uuid,uuid,boolean) to authenticated;grant select on public.teams,public.team_memberships to authenticated;
